use clipboard::ClipboardProvider;
use reqwest::blocking::get;
use serde_json::Value;
use serde_json::from_str;

#[tokio::main]
async fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        println!("Usage: {} <api_key>", args[0]);
        return;
    }

    let api_key = &args[1];

    let clipboard = ClipboardProvider::new().unwrap();
    let clipboard_content = clipboard.get_contents().unwrap();

    if clipboard_content.is_empty() {
        println!("Clipboard is empty.");
        return;
    }

    let response = get("https://api.elevenlabs.io/v1/text-to-speech/synthesize")
        .header("Authorization", format!("Bearer {}", api_key))
        .header("Content-Type", "application/json")
        .json(&json!({
            "text": clipboard_content,
            "voice": "en-US_Wavenet-B",
            "ssml": false
        }))
        .send()
        .await
        .unwrap();

    let audio_data = response.bytes().await.unwrap();

