Create a `TooltipContext` to manage the state of the tooltip and a `useTooltip` hook to use the context in the component.

```jsx
import React, { createContext, useContext, useState } from 'react';

const TooltipContext = createContext();

export const TooltipProvider = ({ children }) => {
  const [tooltip, setTooltip] = useState(null);

  const closeTooltip = () => {
    setTooltip(null);
  };

  const value = { tooltip, setTooltip, closeTooltip };

  return (
    <TooltipContext.Provider value={value}>{children}</TooltipContext.Provider>
  );
};

export const useTooltip = () => {
  const context = useContext(TooltipContext);

  if (!context) {
    throw new Error('useTooltip must be used within a TooltipProvider');
  }

  return context;
};
```

Now, you can use the `TooltipProvider` and `useTooltip` hook in your components to create and manage tooltips.

```jsx
import React from 'react';

const Tooltip = ({ children, placement }) => {
  const { tooltip, setTooltip, closeTooltip } = useTooltip();

  const handleMouseEnter = (event) => {
    if (!tooltip) {
      setTooltip({
        event,
        content: children,
        placement,
      });
    }
  };

  const handleMouseLeave = () => {
    if (tooltip && tooltip.event === event) {
      closeTooltip();
    }
  };

  return (
    <div
      onMouseEnter={handleMouseEnter}
      onMouseLeave={handleMouseLeave}
      role="tooltip"
    >
      {tooltip && (
        <div
          style={{
            position: 'absolute',
            zIndex: 1,
            background: '#fff',
            border: '1px solid #ccc',
            padding: '5px',
            borderRadius: '4px',
            color: '#333',
            fontSize: '14px',
            opacity: 0,
            transition: 'opacity 0.2s',
            pointerEvents: 'none',
            ...getPlacementStyle(placement),
          }}
        >
          {tooltip.content}
        </div>
      )}
      {children}
    </div>
  );
};

const getPlacementStyle = (placement) => {
  const offset = 10;

  switch (placement) {
    case 'top':
      return { top: -offset, left: '50%', transform: 'translateX(-50%)' };
    case 'right':
      return { right: offset, top: '50%', transform: 'translateY(-50%)' };
    case 'bottom':
      return { bottom: offset, left: '50%', transform: 'translateX(-50%)' };
    case 'left':
      return { left: -offset, top: '50%', transform: 'translateY(-50%)' };
    default:
      return {};
  }
};

export default Tooltip;
```

Now, you can use the `Tooltip` component in your pages or components and wrap it with the `TooltipProvider` to manage the tooltip state.

```jsx
import Tooltip from '../components/Tooltip';

const Page = () => {
  return (
    <TooltipProvider>
      <div>
        <Tooltip placement="top">Hover over me</Tooltip>
        {/* More tooltips here */}
      </div>
    </TooltipProvider>
  );
};

export default Page;
```

This way, the tooltip state is managed globally, and the previously opened tooltip will be closed when a new one is opened.

